const budgetFields=[['target','Бюджет всей поездки, ¥'],['people','Человек'],['days','Дней'],['roomNight','Номер за ночь, ¥'],['foodDay','Питание на человека / день, ¥'],['localDay','Городской транспорт на человека / день, ¥'],['transfers','Все переезды по Японии, ¥'],['extra','Покупки и прочее, ¥'],['yenPerPoint','Йен за игровое очко']];
const defaultPath=['osaka','kyoto','nagano','sendai','aomori','hakodate','sapporo','tokyo'];
function freshRaid(){return {version:1,name:'',hero:'tokyo',champion:'tokyo:0',heroes:[{city:'tokyo',id:'tokyo:0'}],exitCity:'tokyo',exitAirport:'hnd',departed:false,path:[...defaultPath],index:0,deck:[],picks:{},cleared:[],draft:[],phase:'setup',secretUnlocked:false,secretActive:false,secretDone:false,secretAt:null,airport:'hnd',badges:[],journey:[],transfer:null,battle:null,seed:Date.now()>>>0,budget:RaidBudget.arrival(),scoreLog:[],seenEvents:{},attempt:1,previousRun:null,expenses:[],costOverrides:{},recoveryUsed:{},recoveryChoice:null,detours:[],scenic:false,interests:['walk','temples']};}
let raid=state.raid?.version===1?state.raid:freshRaid(),selectedHero=raid.hero,selectedChampion=RaidChampions.get(raid.hero,raid.champion,R.heroes[raid.hero]).id,animating=false,unitMarkers=[],journeyMarker=null,transitFrame=0,photoRequest=0,hoverTimer,photoCache=new Map(),combatTimers=new Set();
if(!raid.champion){const legacyPower=['osaka','kyoto'].includes(raid.hero)?raid.hero:'sendai';raid.champion=RaidChampions.choices(raid.hero,R.heroes[raid.hero]).find(h=>h.powerKey===legacyPower).id;selectedChampion=raid.champion;}
raid.heroes=raid.heroes?.length?raid.heroes:[{city:raid.hero,id:raid.champion}];raid.exitCity=raid.exitCity||raid.path.at(-1);raid.departed=raid.departed||raid.phase==='complete';raid.exitAirport=raid.exitAirport||Object.keys(RaidWorld.airports).find(k=>RaidWorld.airports[k].cities.includes(raid.exitCity))||'';
