raid.badges=raid.badges||[...raid.cleared,...(raid.secretDone?['nara']:[])];raid.journey=raid.journey||[];raid.airport=raid.airport||(raid.hero==='sendai'?'sdj':'kix');if(raid.battle)R.prepareEnemy(raid.battle);
raid.budget=RaidBudget.arrival(raid.budget);raid.scoreLog=raid.scoreLog||[];raid.seenEvents=raid.seenEvents||{};raid.attempt=raid.attempt||1;
raid.expenses=raid.expenses||[];raid.costOverrides=raid.costOverrides||{};raid.recoveryUsed=raid.recoveryUsed||{};raid.detours=raid.detours||[];if(raid.battle)R.migrateUnique(raid.battle);
