function arrangeSetup(){const form=$('#raid-create'),columns=document.createElement('div'),journey=document.createElement('div'),budget=document.createElement('div');columns.className='setup-columns';journey.className='setup-journey';budget.className='setup-party';columns.append(journey,budget);form.insertBefore(columns,$('#route-preview'));journey.append(form.querySelector('label[for="raid-city"]'),$('#raid-city'),$('#airport-choice'),form.querySelector('.party-caption'),$('#city-champions'),$('#selected-party'),$('#party-status'));budget.append(form.querySelector('label[for="raid-next-city"]'),$('#raid-next-city'),$('#exit-airport-choice'),form.querySelector('label[for="raid-start-budget"]'),$('#travel-party'),$('#together-count'),$('#raid-start-budget'),$('#start-budget-context'));const fx=document.createElement('div');fx.id='budget-fx';fx.className='fx-block';$('#raid-start-budget').after(fx);const interests=document.createElement('div');interests.id='trip-interests';interests.setAttribute('aria-label','Интересы в путешествии');journey.append(interests);renderInterests();for(const node of [form.querySelector('label[for="hero-city"]'),$('#hero-city')]){node.hidden=true;$('#legacy-start-options').append(node);}$('#route-preview').hidden=true;}


$('#raid-create').onsubmit=e=>{e.preventDefault();if(!selectedParty.length)return;const name=$('#raid-name').value.trim()||raid.name||'Путешественник',exitCity=$('#raid-next-city').value,plan=plannedPath(selectedHero,exitCity),people=$('#travel-party').dataset.people==='1'?1:Number($('#raid-party-size').value);raid=freshRaid();raid.name=name.slice(0,24);raid.hero=selectedHero;raid.heroes=selectedParty.map(h=>({...h}));raid.champion=raid.heroes[0].id;raid.path=plan;raid.exitCity=exitCity;raid.exitAirport=$('#raid-exit-airport').value;raid.scenic=false;raid.interests=[...selectedInterests];raid.airport=$('#raid-airport').value;raid.budget=RaidBudget.arrival({...raid.budget,target:Number($('#raid-start-budget').value),people,transfers:raid.path.length>1?RaidBudget.defaults.transfers*people/2:0});raid.phase='draft';hideInfo();const arrival=RaidWorld.arrival(selectedHero,raid.airport);if(arrival)startTransit(arrival,0,false);else enterCity();};
