document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideInfo();$('#raid-collection').hidden=true;}const modal=!$('#raid-forecast').hidden?$('#raid-forecast'):!$('#raid-collection').hidden?$('#raid-collection'):raid.phase==='setup'?$('#raid-setup'):null;if(e.key==='Tab'&&modal){const controls=[...modal.querySelectorAll('button,input,select,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
if(raid.phase==='battle'&&raid.battle?.result){if(raid.battle.result==='win'){if(raid.secretActive)raid.secretDone=true;else if(!raid.cleared.includes(cityNow()))raid.cleared.push(cityNow());awardBadge();raid.phase='victory';}else raid.phase='defeat';}
raid.deck=raid.phase==='transit'?[]:R.localDeck(cityNow(),raid.deck);raid.draft=R.localDeck(cityNow(),raid.draft||[]).slice(0,3);
if(raid.phase==='battle'&&raid.battle){const old=raid.battle;if([...old.hand,...old.draw,...old.discard,...old.board].some(c=>R.cards[c.id]?.city!==cityNow())){raid.battle=R.battle(raid.deck,cityNow(),raid.index,partyPowers(),old.seed);for(const key of ['hp','maxHP','enemyHP','enemyMax','turn','mana','maxMana'])raid.battle[key]=old[key];}}
