function renderAirports(){if(!$('#raid-city').options.length)refreshCities();$('#raid-city').value=selectedHero;updateCityHero();if(!$('#hero-city').options.length){$('#hero-city').innerHTML=Object.keys(R.heroes).map(c=>`<option value="${c}">${esc(R.cities[c].name)}</option>`).join('');$('#hero-city').value=selectedHero;}renderChampions();renderNextCities();$('#airport-choice').hidden=!['osaka','tokyo'].includes(selectedHero);const choices=Object.entries(RaidWorld.airports).filter(([,a])=>a.cities.includes(selectedHero));$('#raid-airport').innerHTML=choices.map(([id,a])=>`<option value="${id}">${a.code} · ${a.name}${id==='itm'?' · внутренние рейсы':''}</option>`).join('');if(choices.some(([id])=>id===raid.airport))$('#raid-airport').value=raid.airport;airportHelp();renderExitAirports();renderRoutePreview();}
