function currentEstimate(){return RaidBudget.estimate(raid.budget,raid.scoreLog,raid.expenses);}
function yen(value){return '¥ '+new Intl.NumberFormat(window.JapanLocale||'ru-RU',{maximumFractionDigits:0}).format(value);}
function renderDraftBudget(){const planned=currentEstimate();const chapter=raid.draft.reduce((n,id)=>n+RaidTravel.cost(R.cards[id],raid.costOverrides)*raid.budget.people,0);const total=planned.planned+chapter;$('#draft-budget').textContent='План '+yen(total)+' / '+yen(planned.config.target);$('#draft-budget').classList.toggle('over-budget',total>planned.config.target);}

function renderBudget(){const root=$('#raid-budget-result');if(!root.dataset.ready){root.dataset.ready='1';root.innerHTML=`<div class="score-conversion"><div><small>Впечатления путешествия</small><strong id="budget-score"></strong></div><span>${icon('arrow-right')}</span><div><small>Карты и остановки</small><strong id="budget-experiences"></strong></div></div><p id="budget-rate"></p><div class="budget-total"><span>План поездки</span><strong id="budget-total"></strong><p id="budget-context"></p></div><div id="budget-balance"></div><div id="final-budget-fx" class="fx-block"></div><details class="budget-details"><summary>Расходы и настройки расчёта</summary><dl id="budget-breakdown"></dl><details class="budget-scoring"><summary>Расходы по картам и остановкам</summary><ul id="budget-expense-list"></ul></details><details class="budget-settings"><summary>Изменить состав сметы</summary><div class="budget-fields">${budgetFields.filter(([key])=>['target','people','days'].includes(key)).map(([key,label])=>`<label>${label}<input type="number" data-budget="${key}" min="${key==='target'?10000:key==='people'||key==='days'||key==='yenPerPoint'?1:0}" max="${key==='people'?99:key==='days'?90:100000000}" step="${['people','days','yenPerPoint'].includes(key)?1:100}"></label>`).join('')}</div><p>Плановые ставки: замените их ценами своих бронирований. Международные перелёты добавляйте отдельно.</p></details><details class="budget-scoring"><summary>Как считаются впечатления</summary><ul id="budget-score-list"></ul><p>Впечатления каждого пройденного города сохраняются один раз. Повторные попытки их не дублируют. Деньги считаются отдельно по картам и событиям.</p><p id="budget-legacy" hidden>Для старого сохранения учтены только сохранившиеся победы и посещённые места.</p></details></details><section id="budget-relief" hidden></section><section class="budget-replays"><h3>Пройти ещё раз с другим бюджетом</h3><div><button data-budget-replay="0.8"><span>На 20% меньше</span><b id="replay-less"></b></button><button class="raid-primary" data-budget-replay="1"><span>С этим бюджетом</span><b id="replay-same"></b></button><button data-budget-replay="1.2"><span>На 20% больше</span><b id="replay-more"></b></button></div><p id="budget-comparison" hidden></p></section>`;root.append(root.querySelector('.budget-details'));root.querySelectorAll('[data-budget-replay]').forEach(el=>el.onclick=()=>replayBudget(Number(el.dataset.budgetReplay)));root.querySelectorAll('[data-budget]').forEach(el=>{el.value=raid.budget[el.dataset.budget];el.oninput=()=>{if(el.value===''||!Number.isFinite(el.valueAsNumber))return;raid.budget=RaidBudget.normalize({...raid.budget,[el.dataset.budget]:el.valueAsNumber});saveRaid();renderBudget();};el.onchange=()=>el.value=raid.budget[el.dataset.budget];});}
const s=currentEstimate();renderRelief(s);$('#budget-score').textContent=raid.scoreLog.reduce((n,e)=>n+(e.impressions||0),0).toLocaleString(window.JapanLocale||'ru-RU');$('#budget-experiences').textContent=yen(s.rows.experiences);$('#budget-rate').textContent='Плановые расходы выбранных карт и остановок. Бесплатные игровые встречи не добавляют йен.';$('#budget-total').textContent=yen(s.planned);renderFx($('#final-budget-fx'),s.planned);$('#budget-context').textContent=s.config.people+' чел. · '+s.config.days+' дн. · '+s.nights+' ночей · '+s.rooms+' ном.';$('#budget-balance').textContent=s.within?'В бюджете · запас '+yen(s.remaining):'Выше бюджета на '+yen(-s.remaining);$('#budget-balance').classList.toggle('over-budget',!s.within);const names={stay:'Проживание',food:'Питание',local:'Городской транспорт',transfers:'Междугородние переезды',experiences:'Карты и восстановление',extra:'Покупки и прочее'};$('#budget-breakdown').innerHTML=Object.entries(s.rows).map(([key,value])=>`<div><dt>${names[key]}</dt><dd>${yen(value)}</dd></div>`).join('');$('#budget-expense-list').innerHTML=raid.expenses.map(e=>`<li><span>${esc(e.name)}</span><b>${yen(e.costPerPerson*s.config.people)}</b></li>`).join('');$('#budget-score-list').innerHTML=raid.scoreLog.map(e=>`<li><span>${esc(R.cities[e.city]?.name||e.city)}</span><b>${e.impressions||0}</b></li>`).join('');$('#budget-legacy').hidden=!raid.scoreLog.some(e=>e.legacy);$('#replay-less').textContent=yen(RaidBudget.replayTarget(raid.budget,.8));$('#replay-same').textContent=yen(s.config.target);$('#replay-more').textContent=yen(RaidBudget.replayTarget(raid.budget,1.2));if(raid.previousRun){$('#budget-comparison').hidden=false;$('#budget-comparison').textContent='Прошлая попытка: '+raid.previousRun.points+' очков · план '+yen(raid.previousRun.planned)+'.';}}
function replayBudget(factor,adjustment=null){const old=raid,summary=RaidBudget.estimate(old.budget,old.scoreLog,old.expenses),next=RaidBudget.normalize({...old.budget,target:RaidBudget.replayTarget(old.budget,factor)});clearCombatEffects();hideInfo();animating=false;raid=freshRaid();raid.name=old.name;raid.hero=old.hero;raid.champion=old.champion;raid.heroes=old.heroes.map(h=>({...h}));raid.exitCity=old.exitCity;raid.exitAirport=old.exitAirport;raid.scenic=old.scenic;raid.interests=[...(old.interests||['walk','temples'])];raid.path=[...old.path];raid.airport=old.airport;raid.budget=adjustment?.config||next;if(adjustment?.id==='local')raid.path=[old.path[0]];raid.attempt=(old.attempt||1)+1;raid.previousRun={points:summary.points,planned:summary.planned,target:summary.config.target};selectedHero=raid.hero;selectedParty=[{city:raid.hero,id:raid.champion}];$('#raid-budget-result').dataset.ready='';$('#raid-budget-result').replaceChildren();$('#raid-collection').hidden=true;$('#raid-forecast').hidden=true;$('#raid-forecast').dataset.key='';raid.phase='draft';enterCity();}

function flightCityLabel(city){const airport=Object.values(RaidWorld.airports).find(a=>a.cities.includes(city));return R.cities[city].name+(!['osaka','tokyo'].includes(city)&&airport?' · через '+airport.code:'');}
function renderNextCities(){const current=$('#raid-next-city').value||raid.exitCity||'tokyo';$('#raid-next-city').innerHTML=Object.keys(R.heroes).map(c=>`<option value="${c}">${esc(flightCityLabel(c))}</option>`).join('');$('#raid-next-city').value=R.cities[current]?current:selectedHero;}
function plannedPath(start,end){return RaidRoute.scenic(start,selectedParty,RaidWorld.stations,end,selectedInterests).path;}
function renderChampions(){const root=$('#city-champions'),city=$('#hero-city').value||selectedHero,list=RaidChampions.choices(city,R.heroes[city]);root.innerHTML=list.map(h=>`<button type="button" class="champion-choice" data-champion="${h.id}" role="radio" aria-checked="${selectedParty.some(p=>p.id===h.id)}" aria-pressed="${selectedParty.some(p=>p.id===h.id)}"><span class="champion-portrait"><span>${{osaka:'武',kyoto:'知',sendai:'心'}[h.powerKey]}</span><img alt="" hidden></span><b>${esc(h.name)}</b><small>${esc(h.label)}</small></button>`).join('');root.querySelectorAll('[data-champion]').forEach(el=>{const h=list.find(h=>h.id===el.dataset.champion);el.onclick=()=>{partyTouched=true;selectedParty=[{city:h.city,id:h.id}];selectedChampion=h.id;$('#party-status').textContent='';root.querySelectorAll('button').forEach(b=>['aria-pressed','aria-checked'].forEach(attr=>b.setAttribute(attr,String(selectedParty.some(p=>p.id===b.dataset.champion)))));hideInfo();renderRoutePreview();};el.onmouseenter=el.onfocus=()=>showInfo(h.name,h.bio,h.wiki,el,h.power);el.onmouseleave=scheduleHide;photoForTitle(h.wiki).then(photo=>{if(!photo||!el.isConnected)return;const img=el.querySelector('img');img.onload=()=>img.hidden=false;img.src=photo.url;});});}
function renderRoutePreview(){$('#route-preview').hidden=true;$('#route-preview').replaceChildren();const p=selectedParty[0],h=p&&RaidChampions.get(p.city,p.id,R.heroes[p.city]);$('#selected-party').innerHTML=h?`<p class="chosen-hero-power">${esc(h.power)}</p>`:'';$('#raid-create-button').disabled=!h;}

function renderExitAirports(){const city=$('#raid-next-city').value,choices=Object.entries(RaidWorld.airports).filter(([,a])=>a.cities.includes(city));$('#exit-airport-choice').hidden=!['osaka','tokyo'].includes(city);const select=$('#raid-exit-airport'),old=select.value||raid.exitAirport;select.innerHTML=choices.map(([id,a])=>`<option value="${id}">${a.code} · ${a.name}${id==='itm'?' · внутренние рейсы':''}</option>`).join('');if(choices.some(([id])=>id===old))select.value=old;}
function setTravelPeople(people){people=Math.max(1,Math.min(99,Math.round(Number(people)||2)));$('#travel-party').dataset.people=people===1?'1':'2';$('#travel-party').querySelectorAll('button[data-people]').forEach(b=>b.setAttribute('aria-pressed',String((Number(b.dataset.people)===1)===(people===1))));$('#together-count').hidden=people===1;if(people>1)$('#raid-party-size').value=people;$('#together-count').querySelectorAll('[data-party-size]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.partySize)===people)));$('#start-budget-context').textContent='Общая сумма '+(people===1?'на одного':'на '+people+' чел.')+' · 14 дней';}

function departurePoint(){return RaidWorld.airports[raid.exitAirport]?.point||RaidWorld.stations[raid.exitCity];}
function departureTransfer(){const from=raid.path.at(-1),to=raid.exitCity||from,direct=RaidWorld.arrival(from,raid.exitAirport),coords=direct?[...direct.coords].reverse():from===to?[RaidWorld.stations[to]]:RaidWorld.transfer(from,to).coords;const access=direct||RaidWorld.arrival(to,raid.exitAirport);if(access&&!direct)coords.push(...[...access.coords].reverse().slice(1));if(coords.length===1)coords.push([...coords[0]]);return {from,to,coords,departure:true,label:(from!==to?R.cities[from].name+' / '+R.cities[to].name+' · ':'')+(access?RaidWorld.airports[raid.exitAirport].code+' · '+RaidWorld.airports[raid.exitAirport].name:'Обратный вылет из '+R.cities[to].name)};}
function startDeparture(){raid.departed=false;startTransit(departureTransfer(),raid.index,false);}
$('#hero-city').onchange=()=>{renderChampions();renderRoutePreview();};$('#raid-next-city').onchange=()=>{renderExitAirports();renderRoutePreview();};$('#travel-party').querySelectorAll('[data-people]').forEach(b=>b.onclick=()=>setTravelPeople(b.dataset.people==='1'?1:Number($('#raid-party-size').value)||2));$('#raid-party-size').onchange=()=>setTravelPeople(Math.max(2,Number($('#raid-party-size').value)||2));$('#together-count').querySelectorAll('[data-party-size]').forEach(b=>b.onclick=()=>setTravelPeople(Number(b.dataset.partySize)));setTravelPeople(raid.budget.people);

function budgetCeiling(){return raid.path.map(city=>({city,points:145+Object.values(R.cards).filter(c=>c.city===city).map(c=>c.mana).sort((a,b)=>b-a).slice(0,3).reduce((a,b)=>a+b,0)*10}));}
function renderRelief(s){const root=$('#budget-relief');root.hidden=s.within;if(s.within){root.replaceChildren();return;}const options=RaidBudget.relief(raid.budget,raid.scoreLog,raid.expenses).filter(o=>o.id!=='local'||(raid.exitCity===raid.path[0]&&raid.heroes.every(h=>h.city===raid.path[0]))).filter(o=>o.id!=='shorter'||o.config.days>=raid.path.length);root.innerHTML=`<h3>ひと休み · Передышка</h3><p>Маршрут можно пересобрать. Выбери условия для новой попытки в пределах ${yen(s.config.target)}.</p><div>${options.map((o,i)=>`<article><b>${esc(o.title)}</b><strong>${yen(o.planned)}</strong><p>${o.config.days} дн. · номер до ${yen(o.config.roomNight)}/ночь · питание ${yen(o.config.foodDay)}/чел. в день · транспорт ${yen(o.config.localDay)}/чел. в день · переезды ${yen(o.config.transfers)} · покупки ${yen(o.config.extra)}</p><p>${esc(o.note)}</p><button data-relief="${i}" class="raid-primary">Принять условия и переиграть</button></article>`).join('')}</div><small>${options.length?'Варианты рассчитаны по текущим выбранным впечатлениям. Новые карты меняют расходы; ставки можно уточнить по бронированиям.':'Даже короткий вариант не помещается при текущем резерве впечатлений. Ниже можно изменить число путешественников или лимиты расходов.'}</small>`;root.querySelectorAll('[data-relief]').forEach(el=>el.onclick=()=>replayBudget(1,options[Number(el.dataset.relief)]));}

function renderRecovery(){const city=cityNow(),used=raid.recoveryUsed[city]||[],options=RaidTravel.restOptions(city,used,R),remaining=currentEstimate().remaining,root=$('#raid-recovery');root.innerHTML=options.length?`<div class="recovery-options">${options.map(c=>`<article class="recovery-card"><div class="recovery-art" data-art="${c.id}"><img hidden alt=""></div><h3>${esc(c.name)}</h3><p>${esc(c.meaning)}</p><div><strong>+${yen((c.topUp||c.yenRelief)*raid.budget.people)}</strong><b>${yen(c.restCost*raid.budget.people)}</b></div><button class="raid-primary" data-rest="${c.id}" ${c.restCost*raid.budget.people>Math.max(0,remaining)?'disabled':''}>На передышку</button></article>`).join('')}</div><p class="recovery-note">Экономия и встречи — игровые события. Дополнительный обмен увеличивает общий бюджет.</p>`:'<p>Все остановки этого города открыты. Можно собрать новое путешествие.</p><button id="recovery-new-trip" class="raid-primary">Новый маршрут</button>';hydrateArt(root);root.querySelectorAll('[data-rest]').forEach(b=>b.onclick=()=>takeRest(b.dataset.rest));if($('#recovery-new-trip'))$('#recovery-new-trip').onclick=restartGame;}
function takeRest(id){if(raid.phase!=='defeat')return;const c=R.cards[id],remaining=currentEstimate().remaining;if(!c?.recovery||c.restCost*raid.budget.people>Math.max(0,remaining)||!R.recover(raid.battle,id))return;RaidTravel.charge(raid.expenses,c,raid.budget.people,raid.costOverrides,true);if(c.topUp)raid.budget.target+=c.topUp*raid.budget.people;else applySavings(c.yenRelief*raid.budget.people,'rest:'+id,c.name);syncFunds();raid.recoveryUsed[cityNow()]=[...(raid.recoveryUsed[cityNow()]||[]),id];raid.recoveryChoice=id;raid.detours.push({city:cityNow(),id,point:c.point});raid.phase='recovery';saveRaid();enterCity();}
function showRestMap(){const c=R.cards[raid.recoveryChoice];if(!c)return;Villain3D.hide();raidPins();journeyMarker?.setLngLat(c.point);if(journeyMarker)journeyMarker.getElement().hidden=false;screenMap.flyTo({center:c.point,zoom:15.5,pitch:55,duration:1600});}
function renderRestStop(){const c=R.cards[raid.recoveryChoice];if(!c)return;const root=$('#raid-rest-stop');root.innerHTML=`<small>寄り道 · НОВАЯ ОСТАНОВКА</small><h2>${esc(c.name)}</h2><p>${esc(c.meaning)}</p><strong>${yen(raid.battle.hp)}</strong><p>Новая карта в руке. У босса по-прежнему ${raid.battle.enemyHP} впечатлений до победы.</p><button id="return-to-boss" class="raid-primary">Вернуться к боссу ${icon('swords')}</button>`;$('#return-to-boss').onclick=()=>{raid.recoveryChoice=null;raid.phase='battle';saveRaid();enterCity();};}

function renderFx(root,amount){if(!root)return;const values=RaidFx.convert(amount,fxSnapshot);if(!values){root.textContent=fxSnapshot?'Введи сумму бюджета.':'Курс валют временно недоступен.';return;}root.innerHTML=`<div>${RaidFx.codes.map(code=>`<span><small>${code}</small><b>≈ ${new Intl.NumberFormat(window.JapanLocale||'ru-RU',{style:'currency',currency:code,maximumFractionDigits:code==='RUB'?0:2}).format(values[code])}</b></span>`).join('')}</div><p>${fxSnapshot.stale?'Сохранённый курс · ':'Курс · '}${new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(fxSnapshot.date))} · <a href="https://www.exchangerate-api.com" target="_blank" rel="noopener noreferrer">ExchangeRate-API</a></p>`;}

function renderInterests(){const root=$('#trip-interests');root.innerHTML='<p>Что хочется открыть</p>'+Object.entries(R.activityThemes).map(([key,t])=>`<button type="button" data-interest="${key}" aria-pressed="${selectedInterests.includes(key)}">${esc(t.label)}</button>`).join('');root.querySelectorAll('button').forEach(b=>b.onclick=()=>{const key=b.dataset.interest;if(selectedInterests.includes(key)){if(selectedInterests.length===1)return;selectedInterests=selectedInterests.filter(k=>k!==key);}else selectedInterests.push(key);renderInterests();});}

function economyOptions(){return {funds:Math.max(0,currentEstimate().remaining),people:raid.budget.people,cardCosts:Object.fromEntries(Object.values(R.cards).map(c=>[c.id,RaidTravel.cost(c,raid.costOverrides)*raid.budget.people]))};}
function syncFunds(){if(raid.battle?.monetary)raid.battle.hp=Math.max(0,currentEstimate().remaining);}
function applySavings(amount,key,name){if(!amount||raid.expenses.some(e=>e.key===key))return;raid.expenses.push({key,city:cityNow(),name,costPerPerson:-amount/raid.budget.people,kind:'saving'});}
